-- Better starter photos (Josh, 2026-10-17): each starter recipe moves from its old photo in
-- /images/recipes/ to a new one in /images/dishes/, with that photo's credit (listed on /credits).
-- Only a recipe that still has its old starter photo changes; one given an uploaded photo keeps it.
-- Its edit time is left alone, so the home page's "newest first" doesn't reshuffle.
UPDATE recipes SET data = json_set(data, '$.image', '/images/dishes/apple-crisp.jpg', '$.imageCredit', json('{"author":"jeffreyw","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","sourceUrl":"https://commons.wikimedia.org/w/index.php?curid=32022282","title":"01 Mmm... Apple Crisp with Whipped Cream"}')) WHERE id = 'apple-crisp' AND json_extract(data, '$.image') = '/images/recipes/apple-crisp.jpg';
